import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageTimetable() {
  const [timetable, setTimetable] = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [teachers, setTeachers] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const [formData, setFormData] = useState({ day: 'Monday', time_slot: '', grade: 'Grade 6', subject_id: '', teacher_id: '' });

  const fetchTimetable = () => axios.get('http://localhost:8081/api/timetable').then(res => setTimetable(res.data));
  const fetchSubjects = () => axios.get('http://localhost:8081/api/view-subjects').then(res => setSubjects(res.data));
  const fetchTeachers = () => axios.get('http://localhost:8081/api/view-teachers').then(res => setTeachers(res.data));

  useEffect(() => { fetchTimetable(); fetchSubjects(); fetchTeachers(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/timetable', formData).then((res) => {
      if (res.data.status === "Error") alert("Error: " + res.data.error);
      else { fetchTimetable(); resetForm(); }
    }).catch(() => alert("Server Error!"));
  };

  const handleDelete = (id) => {
    if (window.confirm("Are you sure you want to delete this slots?")) {
      axios.delete(`http://localhost:8081/api/timetable/${id}`).then(() => fetchTimetable());
    }
  };

  const resetForm = () => { setShowForm(false); setFormData({ day: 'Monday', time_slot: '', grade: 'Grade 6', subject_id: '', teacher_id: '' }); };

  // Search filter (විෂය නමින් හෝ ගුරු නමින් සර්ච් කළ හැක)
  const filteredTimetable = timetable.filter(t => 
    (t.subject || '').toLowerCase().includes(searchQuery.toLowerCase()) ||
    (t.teacher || '').toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div style={{ padding: '30px', fontFamily: 'sans-serif', backgroundColor: '#f8fafc', minHeight: '100vh' }}>
      <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 10px rgba(0,0,0,0.05)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2 style={{ margin: 0, color: '#1e293b', fontSize: '20px', display: 'flex', alignItems: 'center', gap: '10px' }}>📅 Manage Class Timetable</h2>
          <div style={{ display: 'flex', gap: '15px' }}>
            <input type="text" placeholder="Search Subject or Teacher..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} style={styles.searchInput} />
            <button onClick={() => setShowForm(true)} style={styles.primaryBtn}>+ Add New Class</button>
          </div>
        </div>

        <table style={{ width: '100%', marginTop: '20px', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead>
            <tr style={{ borderBottom: '2px solid #e2e8f0' }}>
              <th style={styles.th}>No.</th>
              <th style={styles.th}>Day</th>
              <th style={styles.th}>Time Slot</th>
              <th style={styles.th}>Grade</th>
              <th style={styles.th}>Subject</th>
              <th style={styles.th}>Teacher</th>
              <th style={styles.th}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredTimetable.map((t, index) => (
              <tr key={t.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                {/* 🟢 අලුත් පේළිය */}
<td style={styles.td}>{filteredTimetable.length - index}</td>
                <td style={{...styles.td, fontWeight: 'bold', color: '#1e293b'}}>{t.day}</td>
                <td style={{...styles.td, color: '#475569', fontSize: '13px'}}>{t.time_slot}</td>
                <td style={{...styles.td, color: '#64748b', fontSize: '13px'}}>{t.grade}</td>
                <td style={{...styles.td, fontWeight: 'bold', color: '#15803d'}}>{t.subject}</td>
                <td style={{...styles.td, color: '#475569'}}>{t.teacher}</td>
                <td style={styles.td}>
                  <button onClick={() => handleDelete(t.id)} style={styles.iconBtn}>🗑️</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {showForm && (
        <div style={styles.modalOverlay}>
          <div style={styles.modal}>
            <h3 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>➕ Add New Class Slot</h3>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              
              <label style={styles.label}>Select Day</label>
              <select value={formData.day} onChange={e => setFormData({...formData, day: e.target.value})} style={styles.input} required>
                <option value="Monday">Monday</option>
                <option value="Tuesday">Tuesday</option>
                <option value="Wednesday">Wednesday</option>
                <option value="Thursday">Thursday</option>
                <option value="Friday">Friday</option>
                <option value="Saturday">Saturday</option>
                <option value="Sunday">Sunday</option>
              </select>

              <label style={styles.label}>Time Slot (e.g. 8.00 AM - 10.00 AM)</label>
              <input type="text" placeholder="Enter Time Slot" value={formData.time_slot} onChange={e => setFormData({...formData, time_slot: e.target.value})} required style={styles.input} />

              <label style={styles.label}>Select Grade</label>
              <select value={formData.grade} onChange={e => setFormData({...formData, grade: e.target.value})} style={styles.input} required>
                <option value="Grade 6">Grade 6</option>
                <option value="Grade 7">Grade 7</option>
                <option value="Grade 8">Grade 8</option>
                <option value="Grade 9">Grade 9</option>
                <option value="Grade 10">Grade 10</option>
                <option value="Grade 11">Grade 11</option>
                <option value="Grade 12">Grade 12</option>
              </select>

              <label style={styles.label}>Select Subject</label>
              <select value={formData.subject_id} onChange={e => setFormData({...formData, subject_id: e.target.value})} style={styles.input} required>
                <option value="">-- Choose Subject --</option>
                {subjects.map(s => <option key={s.id} value={s.id}>{s.subject_name} ({s.subject_code})</option>)}
              </select>

              <label style={styles.label}>Select Teacher</label>
              <select value={formData.teacher_id} onChange={e => setFormData({...formData, teacher_id: e.target.value})} style={styles.input} required>
                <option value="">-- Choose Teacher --</option>
                {teachers.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
              </select>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '10px' }}>
                <button type="button" onClick={resetForm} style={styles.cancelBtn}>Cancel</button>
                <button type="submit" style={styles.saveBtn}>Add to Timetable</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  searchInput: { padding: '8px 15px', borderRadius: '20px', border: '1px solid #cbd5e1', outline: 'none', width: '240px', fontSize: '13px', backgroundColor: '#f8fafc' },
  primaryBtn: { padding: '8px 15px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' },
  th: { padding: '12px 10px', color: '#64748b', fontWeight: 'bold', fontSize: '13px' },
  td: { padding: '15px 10px', fontSize: '14px', verticalAlign: 'middle' },
  iconBtn: { background: 'none', border: 'none', cursor: 'pointer', fontSize: '16px' },
  modalOverlay: { position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 },
  modal: { backgroundColor: 'white', padding: '25px 30px', borderRadius: '15px', width: '460px', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)' },
  input: { padding: '10px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', width: '100%', boxSizing: 'border-box', outline: 'none', fontSize: '13px', backgroundColor: '#f8fafc' },
  label: { fontSize: '12px', color: '#64748b', fontWeight: 'bold', marginBottom: '-5px' },
  cancelBtn: { padding: '10px 20px', background: 'none', color: '#64748b', border: 'none', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px' },
  saveBtn: { padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px' }
};
